<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['a']??'';if($a==='add')$p->prepare("INSERT INTO categories(name,description,sort_order)VALUES(?,?,?)")->execute([trim($_POST['name']),trim($_POST['description']??''),(int)$_POST['sort_order']]);if($a==='del')$p->prepare("DELETE FROM categories WHERE id=?")->execute([(int)$_POST['id']]);} $rows=$p->query("SELECT c.*,COUNT(s.id) n FROM categories c LEFT JOIN services s ON s.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.id")->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>دسته‌ها</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1000px;margin:30px auto}.card{background:#fff;padding:22px;border-radius:18px;margin:15px 0}input,textarea{width:100%;box-sizing:border-box;padding:11px;margin:7px 0}button{background:#1687d9;color:#fff;border:0;padding:10px 14px;border-radius:8px}.danger{background:#d9534f}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eee}</style><div class=wrap><a href=/admin/index.php>← داشبورد</a><div class=card><h3>➕ افزودن دسته</h3><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=add><input name=name placeholder="نام" required><textarea name=description placeholder="توضیحات"></textarea><input type=number name=sort_order value=0><button>افزودن</button></form></div><div class=card><table><tr><th>نام</th><th>تعداد خدمت</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['n']?></td><td><form method=post onsubmit="return confirm('حذف شود؟')"><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=del><input type=hidden name=id value=<?=$r['id']?>><button class=danger>حذف</button></form></td></tr><?php endforeach;?></table></div></div>
